```python
def add(a, b):
    """Add two numbers."""
    return a + b

def subtract(a, b):
    """Subtract two numbers."""
    return a - b

def multiply(a, b):
    """Multiply two numbers."""
    return a * b

def divide(a, b):
    """Divide two numbers."""
    if b == 0:
        raise ValueError("Cannot divide by zero.")
    return a / b

# Get user input and perform calculations
operations = input("Enter a series of operations separated by spaces: ").split()

for operation in operations:
    try:
        num1, operator, num2 = operation.split()
        if operator == "+":
            result = add(int(num1), int(num2))
        elif operator == "-":
            result = subtract(int(num1), int(num2))
        elif operator == "*":
            result = multiply(int(num1), int(num2))
        elif operator == "/":
            result = divide(int(num1), int(num2))
        else:
            raise ValueError(f"Invalid operator: {operator}")
        print(result)
    except ValueError as e:
        print(e)
```

This program defines four functions for addition, subtraction, multiplication, and division. It then prompts the user for a series of operations separated by spaces, splits the input into individual operations, and performs the calculations using the defined functions. The program handles invalid inputs and division by zero errors.
